export function ambassadorCopy(locale: string): AmbassadorCopy {
  return copy[uiLocale(locale)];
}

/** "{n} files": English and Russian choose the inflected form; other locales have one form. */
export function ambassadorCount(forms: Count, n: number): string {
  if (typeof forms === "string") return forms.replace("{n}", String(n));
  const mod10 = n % 10, mod100 = n % 100;
  const form = forms.few === undefined ? (n === 1 ? forms.one : forms.other)
    : mod10 === 1 && mod100 !== 11 ? forms.one : mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14) ? forms.few : forms.other;
  return form.replace("{n}", String(n));
}
